def test_card_changeling_wayfinder():
    """Changeling Wayfinder: Changeling. When this creature enters, you may search your library for a basic land card, reveal it, put it into your hand, then shuffle."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Changeling Wayfinder")
    _assert_emits(game, ['SEARCH_LIBRARY', 'LIBRARY_SEARCH', 'LIBSEARCH_BEGIN'], "Changeling Wayfinder")

def test_card_rooftop_percher():
    """Rooftop Percher: Changeling. Flying. When this creature enters, exile up to two target cards from graveyards. You gain 3 life."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Rooftop Percher")
    _assert_emits(game, ['LIFE_CHANGE', 'LIFE_GAIN', 'LIFE_LOSS', 'EXILE'], "Rooftop Percher")

def test_card_adept_watershaper():
    """Adept Watershaper: Other tapped creatures you control have indestructible."""
    game, p1, p2 = _new_game()
    create_creature_on_battlefield(game, p1, "Adept Watershaper")
    ally = _spawn(game, p1, subtypes=[], tapped=True, name='Granted Ally')
    assert has_ability(ally, "indestructible", game.state), (
        f"Adept Watershaper: should grant indestructible to a creature you control")

def test_card_brigid_clachan_s_heart():
    """Brigid, Clachan's Heart: Whenever this creature enters or transforms into Brigid, Clachan's Heart, create a 1/1 green and white Kithkin creature token."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Brigid, Clachan's Heart")
    _assert_emits(game, ['CREATE_TOKEN', 'OBJECT_CREATED'], "Brigid, Clachan's Heart")

def test_card_burdened_stoneback():
    """Burdened Stoneback: This creature enters with two -1/-1 counters on it. {1}{W}, Remove a counter: Target creature gains indestructible until end of turn. Activate only as a sorcery."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Burdened Stoneback")
    _assert_emits(game, ['PT_MODIFICATION', 'PT_MODIFIER', 'PT_CHANGE', 'PUMP', 'TEMPORARY_BOOST', 'COUNTER_ADDED', 'COUNTER_REMOVED', 'GRANT_KEYWORD', 'KEYWORD_GRANT', 'GRANT_ABILITY'], "Burdened Stoneback")

def test_card_champion_of_the_clachan():
    """Champion of the Clachan: Flash. As an additional cost to cast this spell, behold a Kithkin and exile it. Other Kithkin you control get +1/+1."""
    game, p1, p2 = _new_game()
    create_creature_on_battlefield(game, p1, "Champion of the Clachan")
    ally = _spawn(game, p1, subtypes=['Kithkin'], power=2, toughness=2, name='Buffed Ally')
    base = 2
    got = get_power(ally, game.state)
    assert got == base + 1, (
        f"Champion of the Clachan: lord should grant +1 power to a kithkin "
        f"(base {base} -> expected {base + 1}, got {got})")

def test_card_clachan_festival():
    """Clachan Festival: When this enchantment enters, create two 1/1 green and white Kithkin creature tokens. {4}{W}: Create a 1/1 green and white Kithkin creature token."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Clachan Festival")
    _assert_emits(game, ['CREATE_TOKEN', 'OBJECT_CREATED'], "Clachan Festival")

def test_card_curious_colossus():
    """Curious Colossus: When this creature enters, each creature target opponent controls loses all abilities, becomes a Coward in addition to other types, and has base power and toughness 1/1."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Curious Colossus")
    _assert_emits(game, ['PT_MODIFICATION', 'PT_MODIFIER', 'PT_CHANGE', 'PUMP', 'TEMPORARY_BOOST'], "Curious Colossus")

def test_card_eirdu_carrier_of_dawn():
    """Eirdu, Carrier of Dawn: Flying, lifelink. Creature spells you cast have convoke. At the beginning of your first main phase, you may pay {B}. If you do, transform Eirdu."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Eirdu, Carrier of Dawn")
    # Deal combat damage from this creature to the opponent player.
    game.emit(Event(type=EventType.DAMAGE, payload={'source': obj.id, 'target': p2.id,
        'amount': max(1, obj.characteristics.power or 1), 'is_combat': True,
        'target_type': 'player'}, source=obj.id))
    _assert_emits(game, ['LIFE_CHANGE', 'LIFE_GAIN', 'LIFE_LOSS'], "Eirdu, Carrier of Dawn")

