    """Encumbered Reejerey: This creature enters with three -1/-1 counters on it. Whenever this creature becomes tapped while it has a -1/-1 counter on it, remove a -1/-1 counter."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Encumbered Reejerey")
    _assert_emits(game, ['PT_MODIFICATION', 'PT_MODIFIER', 'PT_CHANGE', 'PUMP', 'TEMPORARY_BOOST', 'COUNTER_ADDED', 'COUNTER_REMOVED', 'TAP', 'TAP_TARGET', 'FREEZE'], "Encumbered Reejerey")

